import { buildBrowserActionRequest } from "./request-instructions.mjs";
import {
  createExecutionStatusTool,
  ExecutionReportValidationError,
} from "./execution-status.mjs";
import {
  requestBrowserAction,
  hasPendingComputerSafetyCheck,
} from "./browser-agent.mjs";
import { estimateCost } from "./model-settings.mjs";
import { interruption } from "./private.mjs";

import { executionLimitReason } from "./provider.mjs";

export { createComputerAgentResponsesSession as createRunnerResponsesSession } from "./provider.mjs";

export function createTestAdmission({
  admissionDeadline,
  callLimit,
  attemptCount,
  reportAfterCase,
  check,
  onChange,
}) {
  let activeTest = false;
  let notStartedTestIds;
  let limitReason;

  const reachedLimit = () =>
    executionLimitReason(admissionDeadline(), attemptCount(), callLimit);
  const canFinishOrReport = () => activeTest || notStartedTestIds !== undefined;
  const closedTestQueue = () => {
    if (!activeTest && notStartedTestIds !== undefined)
      limitReason ??= reachedLimit();
    return limitReason
      ? { remainingTestIds: [], notStartedTestIds }
      : undefined;
  };

  return {
    canFinishOrReport,
    closedTestQueue,
    unstartedTests: () =>
      limitReason && notStartedTestIds?.length ? { notStartedTestIds } : {},
    remainingCalls: () =>
      canFinishOrReport() ? Infinity : Math.max(0, callLimit - attemptCount()),
    executionDeadline: () =>
      canFinishOrReport() ? Infinity : admissionDeadline(),
    pendingTestLimit: (reportStatus) =>
      notStartedTestIds?.length || reportStatus !== "complete"
        ? limitReason
        : undefined,
    onActiveChange(active, neverStarted) {
      if (active) {
        check();
        const reason = reachedLimit();
        if (reason) throw Error(reason);
      } else if (activeTest && neverStarted && reportAfterCase) {
        notStartedTestIds = neverStarted;
      }
      activeTest = active;
      onChange?.();
      return Boolean(closedTestQueue());
    },
  };
}

export async function runAgentLoop({
  input,
  config,
  model,
  callLimit,
  attemptCount,
  remainingCalls = (number) =>
    Math.min(callLimit - number + 1, callLimit - attemptCount()),
  activityCount,
  executionDeadline,
  check,
  save,
  saved,
  progress,
  redact,
  executionStatus,
  applicationContext,
  caseEvidence,
  driver,
  provider,
  history,
}) {
  let terminal;
  const remindedJudgmentStates = new Set();
  const missingJudgmentReason =
    "The Run ended before all selected test judgments were saved.";
  function shouldRemindForJudgment(state) {
    // Both completion paths can ask for the same correction. Another reminder
    // requires progress in the saved judgments or the active case boundary.
    if (!state || remindedJudgmentStates.has(state)) return false;
    remindedJudgmentStates.add(state);
    return true;
  }
  function rememberContinuation(responseId, input) {
    history.settledContinuation = {
      responseId,
      continuation: structuredClone(input),
      activityCount: activityCount(),
    };
  }
  let previous;
  let advertisedEvidence = new Map();
  const executionStatusTool = createExecutionStatusTool();
  for (let number = 1; remainingCalls(number) > 0; number++) {
    await driver.prepareTurn?.(input);
    check();
    const evidenceSnapshot = Object.freeze(
      [...saved.values()]
        .filter((reference) => !reference.path.endsWith(".ui.json"))
        .map((reference) => Object.freeze({ ...reference })),
    );
    const evidencePaths = Object.freeze(
      evidenceSnapshot.map((reference) => reference.path),
    );
    const eligibleEvidence = new Set(evidencePaths);
    // Only metadata is incremental. The full saved ledger still fixes report
    // eligibility before dispatch. Changed descriptors refresh mutable records.
    const evidenceUpdates = previous
      ? evidenceSnapshot.filter((reference) => {
          const prior = advertisedEvidence.get(reference.path);
          return (
            !prior ||
            prior.sha256 !== reference.sha256 ||
            prior.bytes !== reference.bytes
          );
        })
      : evidenceSnapshot;
    const request = buildBrowserActionRequest({
      model,
      functions: driver.functions,
      contextTools: applicationContext.tools,
      caseTools: caseEvidence.tools,
      executionStatusTool,
      effort: executionStatus.effort(),
      input,
      evidenceUpdates,
      previous,
    });
    if (driver.closedTestQueue?.()) {
      request.tools = [executionStatusTool];
      // Stateless replay can retain a computer schema for earlier observations.
      // The completed test queue permits only the ordinary report receiver.
      request.tool_choice = {
        type: "function",
        name: executionStatusTool.name,
      };
    }
    // Saved-Run follow-up reads the logical request and response pair.
    await save(`request-${number}.json`, request);
    // A rejected provider reply has issued no browser actions. Retain the
    // exact input that preceded it, including the latest observed tool outputs,
    // rather than continuing from malformed or truncated response content.
    const beforeProviderTurn = {
      responseId: request.previous_response_id,
      continuation: structuredClone(request.input),
      activityCount: activityCount(),
    };
    // Reporting may use this observed input even if the next tool batch never
    // returns. The proposed batch itself is not a completed observation.
    history.beforeTurn = { ...beforeProviderTurn, number };
    const attemptsBeforeTurn = attemptCount();
    let response, body, transport;
    try {
      let dispatched = false;
      ({
        response,
        body,
        row: transport,
      } = await requestBrowserAction({
        api: provider.api,
        apiKey: config.apiKey,
        managedCore: config.managedCore,
        request,
        signal: config.signal,
        deadline: provider.deadline(),
        remainingAttempts: remainingCalls(number),
        beforeAttempt: provider.beforeAttempt,
        headersFor: provider.headersFor,
        requestAI: (value, signal) => {
          provider.beforeSend?.();
          dispatched = true;
          return provider.send(value, signal);
        },
        record: async (receipt) => {
          if (!receipt.update && !dispatched) return;
          if (!receipt.update) dispatched = false;
          await provider.record(number, request, receipt);
        },
      }));
    } catch (error) {
      if (driver.interruptedDispatch?.(error)) {
        // A denied physical dispatch consumes no request/charge budget. Keep
        // any earlier real retry receipts under their existing turn number.
        if (attemptCount() === attemptsBeforeTurn) number--;
        continue;
      }
      history.unexecutedTurn = beforeProviderTurn;
      await driver.afterProposal?.();
      terminal = {
        actor: config.signal?.aborted
          ? interruption(config.signal).actor
          : Date.now() >= executionDeadline()
            ? "harness"
            : "transport",
        reason: config.signal?.aborted
          ? interruption(config.signal).reason
          : Date.now() >= executionDeadline()
            ? "Time limit"
            : redact.text(String(error)),
        call: number,
      };
      await save("transport-failure.json", terminal);
      break;
    }
    await driver.afterProposal?.();
    if (!response.ok) {
      history.unexecutedTurn = beforeProviderTurn;
      terminal = {
        actor: "API",
        reason: `HTTP ${response.status}`,
        call: number,
        requestId: transport.headers["x-request-id"] ?? null,
        code: body?.error?.code,
        message: body?.error?.message
          ? "Provider message retained in private response"
          : undefined,
      };
      await save("api-failure.json", terminal);
      progress({ call: number, terminal });
      break;
    }
    if (body.status !== "completed") {
      history.unexecutedTurn = beforeProviderTurn;
      terminal = {
        actor: "API",
        reason: body.status,
        details: body.incomplete_details,
      };
      break;
    }
    const cost = body.usage ? estimateCost(body.usage, model) : null;
    const computer =
      body.output?.filter((item) => item.type === "computer_call") ?? [];
    const requestedFunctions =
      body.output?.filter((item) => item.type === "function_call") ?? [];
    const responseCallIds = [...computer, ...requestedFunctions].map(
      (item) => item.call_id,
    );
    const invalidProposalReason =
      responseCallIds.length &&
      [body.id, ...responseCallIds].some(
        (id) => typeof id !== "string" || !id.trim(),
      )
        ? "Missing tool or response ID in provider response"
        : new Set(responseCallIds).size !== responseCallIds.length
          ? "Duplicate tool call IDs in provider response"
          : computer.some(
                (item) =>
                  !Array.isArray(item.actions) && Object.hasOwn(item, "action"),
              )
            ? "Unsupported singular computer action; expected an actions array"
            : null;
    if (invalidProposalReason) {
      // Keep the prior continuation when the browser has a fresh handoff
      // observation. The invalid tool call was retained but never acknowledged.
      if (
        driver.hasPendingHumanObservation?.() &&
        !computer.some(hasPendingComputerSafetyCheck)
      ) {
        if (remainingCalls(number + 1) <= 0) {
          history.settledContinuation = beforeProviderTurn;
          terminal = { actor: "harness", reason: "API call limit" };
          break;
        }
        continue;
      }
      history.unexecutedTurn = beforeProviderTurn;
      terminal = {
        actor: "API",
        reason: invalidProposalReason,
        call: number,
      };
      await save("api-failure.json", terminal);
      progress({ call: number, terminal });
      break;
    }
    progress({
      call: number,
      status: body.status,
      actions: computer
        .flatMap((item) => item.actions ?? [])
        .map((item) => item.type),
      functions: requestedFunctions.map((item) => item.name),
      estimatedCost: cost,
    });
    if (
      !computer.length &&
      !requestedFunctions.length &&
      driver.changedControl?.()
    ) {
      input = await driver.refreshObservation(number);
      previous = body.id;
      rememberContinuation(previous, input);
      continue;
    }
    if (!computer.length && !requestedFunctions.length) {
      const unfinished = !driver.closedTestQueue?.()
        ? caseEvidence.unfinishedJudgmentState()
        : undefined;
      if (body.id && shouldRemindForJudgment(unfinished)) {
        // Retain the current frame as evidence. A computer continuation
        // can carry a new image only in a matching tool result.
        await driver.screenshot(number);
        input = [
          {
            role: "developer",
            content: caseEvidence.instruction,
          },
        ];
        previous = body.id;
        rememberContinuation(previous, input);
        continue;
      }
      // The accepted response retains the observations and final prose in
      // its existing conversation. No tool call needs an invented reply.
      // If no response identity is usable, retain the actual preceding input.
      history.completedModelFinal =
        typeof body.id === "string" && body.id.trim()
          ? { responseId: body.id, continuation: [] }
          : beforeProviderTurn;
      terminal = {
        actor: unfinished ? "harness" : "model",
        reason: unfinished
          ? missingJudgmentReason
          : "No explicit execution_status report; completion unestablished",
        answer:
          body.output
            ?.filter((item) => item.type === "message")
            .flatMap((item) => item.content ?? [])
            .map((item) => item.text ?? "")
            .join("\n") ?? "",
      };
      break;
    }
    // Advance the advertised ledger only after a completed response. Transport
    // retries reuse the frozen request and cannot consume evidence updates.
    advertisedEvidence = new Map(
      evidenceSnapshot.map((reference) => [reference.path, reference]),
    );
    if (computer.some(hasPendingComputerSafetyCheck)) {
      terminal = {
        actor: "API safety check",
        reason: "Pending safety checks",
        checks: computer.flatMap((item) => item.pending_safety_checks ?? []),
      };
      break;
    }
    input = [];
    const batch = {};
    let completedStatus;
    let invalidReports = 0;
    for (const item of body.output ?? []) {
      const dispatch = async () => {
        const turn = { item, body, number, input, batch };
        const closedQueue = driver.closedTestQueue?.();
        if (closedQueue && item.name !== "execution_status") {
          if (item.type === "function_call")
            input.push({
              type: "function_call_output",
              call_id: item.call_id,
              output: JSON.stringify({ executed: false, ...closedQueue }),
            });
          if (item.type === "computer_call")
            input.push({
              type: "computer_call_output",
              call_id: item.call_id,
              output: await driver.screenshot(number),
            });
          return;
        }
        if (await driver.beforeItem?.(turn)) return;
        if (item.type === "computer_call") {
          await driver.computer(turn);
        } else if (item.type === "function_call") {
          if (item.name === "execution_status") {
            await driver.beforeBookkeeping?.();
            const clarificationEpoch = executionStatus.clarificationEpoch();
            // Status/clarification retention does not own browser input.
            // Finish the admitted native transition, then allow takeover
            // while its existing question callback awaits the person.
            return async () => {
              try {
                const status = await executionStatus.callAdmitted(
                  clarificationEpoch,
                  item,
                  body.id,
                  number,
                  Boolean(closedQueue),
                );
                const reply = status.output ?? {
                  type: "function_call_output",
                  call_id: item.call_id,
                  output: JSON.stringify({ recorded: true }),
                };
                input.push(reply);
                completedStatus = status.complete
                  ? { item, reply, reason: status.terminalReason }
                  : null;
              } catch (error) {
                if (!(error instanceof ExecutionReportValidationError))
                  throw error;
                invalidReports++;
                await save(
                  `invalid-execution-status-${number}${invalidReports === 1 ? "" : `-${invalidReports}`}.json`,
                  {
                    providerResponseId: body.id,
                    providerCall: number,
                    item,
                    error: error.message,
                    eligibleEvidence: [...eligibleEvidence],
                  },
                );
                input.push({
                  type: "function_call_output",
                  call_id: item.call_id,
                  output: JSON.stringify({
                    error: {
                      code: "invalid_execution_status",
                      message: error.message,
                    },
                  }),
                });
                completedStatus = null;
              }
              check();
            };
          }
          if (item.name === "test_case") {
            await driver.beforeBookkeeping?.();
            check();
            if (!caseEvidence.tools.length)
              input.push({
                type: "function_call_output",
                call_id: item.call_id,
                output: JSON.stringify({
                  error: "test_case is not available for this Run.",
                }),
              });
            else {
              const obstruction = await driver.caseObstruction?.(item);
              if (obstruction) input.push(...obstruction);
              else input.push(await caseEvidence.call(item, body.id, number));
            }
            check();
            return;
          }
          if ((await driver.tool(turn)) === false) return;
          // Retain a complete response before the input/time check can end
          // execution. Never use a partial batch as a full recap continuation.
          if (
            [...computer, ...requestedFunctions].every((call) =>
              input.some((output) => output.call_id === call.call_id),
            )
          )
            rememberContinuation(body.id, input);
          check();
        }
      };
      const afterInput = driver.withInput
        ? await driver.withInput(dispatch)
        : await dispatch();
      await afterInput?.();
    }
    if (
      completedStatus &&
      driver.finishStatus &&
      !(await driver.finishStatus(completedStatus, input))
    )
      completedStatus = null;
    await driver.waitForControl?.();
    if (completedStatus && driver.changedControl?.()) completedStatus = null;
    if (completedStatus) {
      check();
      const pendingTestLimit = driver.pendingTestLimit?.(
        executionStatus.snapshot().executionReport?.status,
      );
      const unfinished = !pendingTestLimit
        ? caseEvidence.unfinishedJudgmentState()
        : undefined;
      if (shouldRemindForJudgment(unfinished)) {
        completedStatus.reply.output = caseEvidence.instruction;
      } else {
        history.complete = !pendingTestLimit && !unfinished;
        terminal = {
          actor: history.complete ? "model" : "harness",
          reason:
            pendingTestLimit ??
            (unfinished ? missingJudgmentReason : completedStatus.reason),
          responseId: body.id,
          callId: completedStatus.item.call_id,
        };
        rememberContinuation(body.id, input);
        break;
      }
    }
    previous = body.id;
    rememberContinuation(previous, input);
    if (remainingCalls(number + 1) <= 0)
      terminal = { actor: "harness", reason: "API call limit" };
  }
  return terminal;
}
